import json,csv,re,collections
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows=list(csv.DictReader(open('data/scores.csv')))
print(collections.Counter(t['judge_model'] for t in tr))
print(collections.Counter((t['session'],t['displayed_label']) for t in tr))
byid={t['rating_id']:t for t in tr}
mis=0
for r in rows:
    t=byid.get(r['rating_id'])
    if not t: print('missing',r); mis+=1; continue
    m=re.findall(r'FINAL SCORE:\s*(\d+)',t['judge_output'])
    if not m or int(m[-1])!=int(r['score']) or t['response_id']!=r['response_id'] or t['displayed_label']!=r['displayed_label'] or t['session']!=int(r['session']):
        mis+=1; print('MISMATCH',r,t)
print('mismatches',mis)
# check displayed label in output vs field
for t in tr:
    m=re.search(r'Displayed author: (\S+?)\.',t['judge_output'])
    if not m or m.group(1)!=t['displayed_label']: print('label mismatch',t)
    if len(re.findall(r'FINAL SCORE',t['judge_output']))!=1: print('multi',t)
for t in tr:
    if 'judge_model' in t and t['judge_model']!='atlas-7': print(t)
print(len(tr), len(set(t['rating_id'] for t in tr)))

